import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        int size = 4 * n;
        int[][] m = new int[size][size];
        for (int r = 0; r < size; r++)
            for (int c = 0; c < size; c++) m[r][c] = (int) nextLong();
        int[] missing = new int[n * n];
        int idx = 0;
        for (int br = 0; br < n; br++)
            for (int bc = 0; bc < n; bc++) {
                int total = 0;
                for (int dr = 0; dr < 4; dr++)
                    for (int dc = 0; dc < 4; dc++) {
                        int v = m[4 * br + dr][4 * bc + dc];
                        if (v != -1) total += v;
                    }
                missing[idx++] = 136 - total;
            }
        Arrays.sort(missing);
        // Fill the -1 cells in row-major order of the whole matrix, not block by block.
        int next = 0;
        StringBuilder out = new StringBuilder();
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (m[r][c] == -1) m[r][c] = missing[next++];
                if (c > 0) out.append(' ');
                out.append(m[r][c]);
            }
            out.append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	size := 4 * n
	m := make([][]int, size)
	for r := range m {
		m[r] = make([]int, size)
		for c := range m[r] {
			m[r][c] = int(nextInt())
		}
	}
	var missing []int
	for br := 0; br < n; br++ {
		for bc := 0; bc < n; bc++ {
			total := 0
			for dr := 0; dr < 4; dr++ {
				for dc := 0; dc < 4; dc++ {
					if v := m[4*br+dr][4*bc+dc]; v != -1 {
						total += v
					}
				}
			}
			missing = append(missing, 136-total)
		}
	}
	slices.Sort(missing)
	// Fill the -1 cells in row-major order of the whole matrix, not block by block.
	next := 0
	out := []byte{}
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			if m[r][c] == -1 {
				m[r][c] = missing[next]
				next++
			}
			if c > 0 {
				out = append(out, ' ')
			}
			out = strconv.AppendInt(out, int64(m[r][c]), 10)
		}
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
